skin:
#s99 .stage{background:linear-gradient(180deg,#0a1520,#101c28);color:#FFB454;font-family:var(--mono)}
#s99 .d-nav{background:#0d1a26;border:1px solid #2a4a63;border-radius:2px;box-shadow:inset 0 1px 0 #ffffff1a,0 0 24px #ffb45414}
#s99 .d-logo{letter-spacing:.2em;color:#7DF9FF;text-shadow:0 0 12px #7df9ff80}
#s99 .d-links span{opacity:.6;color:#5f7f99;letter-spacing:.1em}#s99 .d-links span:hover{opacity:1;color:#FFB454}
#s99 .d-h{letter-spacing:.12em;font-weight:500;text-shadow:0 0 14px #ffb45466}
#s99 .d-p{color:#8fa9bd}
#s99 .d-btn{background:#FFB454;color:#0a1520;border:1px solid #ffd18f;border-radius:2px;box-shadow:0 0 18px #ffb4544d,inset 0 -2px 0 #b8791f;font-weight:700;letter-spacing:.1em}
#s99 .d-btn:hover{filter:brightness(1.1)}
#s99 .d-btn.ghost{background:#16283a;color:#7DF9FF;border:1px solid #2a4a63;box-shadow:0 0 12px #7df9ff26}
#s99 .d-input{background:#050b12;border:1px solid #2a4a63;color:#7DF9FF;box-shadow:inset 0 0 12px #00000080;caret-color:#7DF9FF}
#s99 .d-badge{background:#16283a;color:#FFB454;border:1px solid #2a4a63;border-radius:2px;letter-spacing:.1em}
#s99 .d-prog{background:#050b12;border:1px solid #2a4a63;border-radius:0}#s99 .d-prog i{background:repeating-linear-gradient(90deg,#FFB454 0 6px,#050b12 6px 8px)}
#s99 .d-card{background:#0d1a26;border:1px solid #2a4a63;border-radius:2px;box-shadow:inset 0 0 30px #ffb4540d}
